import { createApp, reactive, nextTick } from 'vue';
import { createRouter, createMemoryHistory } from 'vue-router';
import { PreviewApp, PreviewHome, PreviewView } from './preview/archivePreviewComponents';
import { archiveDemoState, HOME_DEMO_TIMING, ACCESS_GALLERY_STOPS, exhibitionDemoTiming } from './utils/archiveDemoTimeline';
import ArrowUpRightIcon from './components/ui/ArrowUpRightIcon.vue';
import SiteIcon from './components/ui/SiteIcon.vue';
import { handwritingDirective } from './utils/siteHandwriting';
import snapshot from './data/archiveDemoView.json';
import PreviewGallery from './preview/ArchivePreviewGallery';
import './assets/css/scroll-animations.css';
import './assets/css/ask-related.css';
import './assets/css/text-links.css';
import './assets/css/archive-preview.css';

const clock = reactive({ dark: false, scene: 'home', state: archiveDemoState('home', 0), playing: false, exhibition: false, exhibitionReady: false, composeStartedAt: 0, viewportWidth: innerWidth, viewportHeight: innerHeight });
const router = createRouter({ history: createMemoryHistory(), routes: [
  { path: '/home', component: PreviewHome, meta: { monochromeHome: true } },
  { path: '/views', component: PreviewGallery },
  { path: '/view/:shareId', component: PreviewView },
  { path: '/:pathMatch(.*)*', component: PreviewHome, meta: { monochromeHome: true } },
] });
const app = createApp(PreviewApp);
app.provide('previewClock', clock);
app.component('ArrowUpRightIcon', ArrowUpRightIcon);
app.component('SiteIcon', SiteIcon);
app.directive('handwriting', handwritingDirective);
app.use(router);

function ease(value) { const t = Math.max(0, Math.min(1, value)); return 1 - (1 - t) ** 3; }
let route = '/home';
let pointer;
let bezel;
let bezelShape = '';
let root;
let prepared = false;
let pointerGesture = null;
let pointerOrigin = null;
let pointerDestination = null;
let pointerPosition = null;
let pointerTime = -1;
let pointerScene = '';
let hoveredControl = null;

// Each gesture ends on a production control. The pause before a click makes
// the destination legible, and the following frame carries its visual response.
function previewGesture(scene, time, mobile, touch) {
  const gestures = [];
  const add = (selector, click, lead = 1000) => gestures.push({ selector, click, start: click - lead });
  if (scene === 'home' || scene === 'access-home') {
    add('.mono-ask input', HOME_DEMO_TIMING.typingAt - 70, 850);
    add('.mono-ask button', HOME_DEMO_TIMING.submitAt - 40, 900);
    if (scene === 'home') {
      add('.sp-ask-view-offer-button', HOME_DEMO_TIMING.composeAt - 50, 1100);
      add('.exhibition-invitation .view-presentation-choice button', HOME_DEMO_TIMING.visitClickAt, 1100);
    }
  }
  if (scene === 'palette') {
    add(mobile ? '.mobile-global-control' : '.search-trigger', 1050, 950);
    for (const [index, click] of [[1, 4500], [2, 7700], [4, 10900]]) {
      if (mobile) {
        add('.sp-mobile-mode-trigger', click - 650, 650);
        add(`.sp-mobile-mode-option:nth-child(${index})`, click - 50, 500);
      } else add(`.sp-mode:nth-child(${index})`, click - 50, 950);
    }
  }
  if (scene === 'exhibition' || scene === 'access-exhibition') {
    const compact = matchMedia('(max-width:767px), (max-width:1180px) and (max-height:600px)').matches;
    const { beginAt, stepDuration } = exhibitionDemoTiming(scene, touch);
    add(compact ? '.exhibition-mobile-start' : '.exhibition-begin', beginAt - 50);
    for (const step of [1, 2, 3]) add('.exhibition-navigation [aria-label="Next stop"]', beginAt + step * stepDuration - 50);
  }
  if (scene === 'access-gallery') {
    const nav = '.museum-footer .museum-nav-stop';
    for (const stop of ACCESS_GALLERY_STOPS.slice(1)) {
      const index = { hall: 1, directory: 2, collection: 3 }[stop.area];
      add(`${nav}:nth-child(${index}) > .museum-control`, stop.at - 50);
    }
    add('.museum-collection-toolbar .museum-panel-toggle', 6850);
  }
  if (scene === 'access-header' || scene === 'access-sidebar') {
    add(mobile ? '.mobile-global-control' : scene === 'access-sidebar' ? '.margin-dock-search' : '.search-trigger', scene === 'access-sidebar' ? 5700 : 3500, 1100);
  }
  return gestures.find(gesture => time >= gesture.start && time < gesture.click + 320);
}

async function renderFrame(message) {
  if (!prepared) return;
  clock.scene = message.scene;
  clock.state = archiveDemoState(message.scene, message.elapsed, Boolean(message.touch));
  clock.playing = message.playing;
  clock.viewportWidth = innerWidth;
  clock.viewportHeight = innerHeight;
  const touch = message.touch ?? innerWidth <= 760;
  pointer.classList.toggle('is-touch', touch);
  clock.exhibition = Boolean(message.exhibition) && (['exhibition', 'access-exhibition'].includes(message.scene) || clock.state.atEntrance);
  document.documentElement.classList.toggle('dark-mode', message.dark);
  document.body.classList.toggle('dark-mode', message.dark);
  clock.dark = Boolean(message.dark);
  document.body.classList.toggle('preview-paused', !message.playing);
  document.body.classList.toggle('preview-reduced-motion', !!message.reducedMotion);
  document.body.classList.toggle('preview-home-journey', message.scene === 'home');
  const radius = Number(message.cornerRadius) || 0;
  const shape = `${innerWidth}:${innerHeight}:${radius}:${message.dark}`;
  if (shape !== bezelShape) {
    bezelShape = shape;
    bezel.style.display = radius ? 'block' : 'none';
    const w = innerWidth, h = innerHeight, r = radius;
    bezel.setAttribute('viewBox', `0 0 ${w} ${h}`);
    bezel.style.fill = message.dark ? '#1c1c1e' : '#fff';
    // Four separate corners avoid coincident edges along the screen perimeter,
    // which can rasterise as a rectangular hairline when the iframe is scaled.
    bezel.firstElementChild.setAttribute('d', `M0 0H${r}A${r} ${r} 0 0 0 0 ${r}Z M${w} 0V${r}A${r} ${r} 0 0 0 ${w-r} 0Z M${w} ${h}H${w-r}A${r} ${r} 0 0 0 ${w} ${h-r}Z M0 ${h}V${h-r}A${r} ${r} 0 0 0 ${r} ${h}Z`);
  }
  if (clock.state.phase === 'composing' && !clock.composeStartedAt) clock.composeStartedAt = Date.now();
  if (clock.state.phase !== 'composing') clock.composeStartedAt = 0;
  const next = clock.state.phase === 'gallery' ? '/views?galleryFrame=1&showcaseControls=1' : ['reading', 'access'].includes(clock.state.phase) ? `/view/${snapshot.id}?temporaryPresentation=1&galleryFrame=1&showcase=linkedJourney&showcaseControls=1&showcaseChannel=archive-intro` : '/home';
  if (next !== route) {
    route = next;
    // The preview clock owns its route. A memory router cannot change the
    // visitor's URL, browser history, saved Ask, View or return position.
    await router.replace(next);
    window.scrollTo({ top: 0, behavior: 'instant' });
  }
  await nextTick();
  const mobile = innerWidth <= 760;
  const state = clock.state;
  let y = 0;
  if (next === '/home') {
    const answer = document.querySelector('.mono-answer-scroll');
    const offer = answer?.querySelector('.sp-ask-view-offer-button');
    if (answer && offer) {
      // Let a short phone screen read the answer before bringing its View
      // control into reach. This is the real answer's internal scroll area.
      const bottom = offer.getBoundingClientRect().bottom - answer.getBoundingClientRect().top + answer.scrollTop;
      answer.scrollTop = Math.max(0, bottom - answer.clientHeight + 20) * ease((state.time - HOME_DEMO_TIMING.answerScrollAt) / 1000);
    } else if (answer) answer.scrollTop = 0;
  }
  if (clock.state.phase === 'reading' && (!clock.exhibition || message.scene === 'home')) {
    const figure = document.querySelector('.view-illustration');
    const cover = figure ? Math.max(0, figure.getBoundingClientRect().top + scrollY - (mobile ? 110 : 160)) : 0;
    y = cover * ease((state.time - HOME_DEMO_TIMING.coverScrollAt) / 1600);
  }
  if (message.scene === 'access-sidebar') y = (mobile ? 540 : 640) * ease((state.time - 900) / 2100);
  if (Math.abs(window.scrollY - y) > .5) window.scrollTo({ top: y, behavior: 'instant' });
  document.body.classList.toggle('home-mobile-hero-past', y > 80 || next !== '/home');
  root.mobileHomeHeaderReady = true;
  root.marginDockActive = message.scene === 'access-sidebar' && !mobile && y > 200;

  const t = state.time;
  if (pointerScene !== message.scene || t < pointerTime) {
    pointerGesture = null; pointerOrigin = null; pointerDestination = null; pointerPosition = null;
    hoveredControl?.removeAttribute('data-preview-hover');
    hoveredControl?.removeAttribute('data-preview-pressed'); hoveredControl = null;
  }
  pointerScene = message.scene; pointerTime = t;
  const gesture = previewGesture(message.scene, t, mobile, touch);
  const gestureId = gesture ? `${message.scene}:${gesture.click}` : null;
  let target = gesture ? document.querySelector(gesture.selector) : null;
  if (target && !target.getBoundingClientRect().width) target = null;
  if (gestureId !== pointerGesture) {
    pointerOrigin = pointerPosition || { x: innerWidth * .62, y: innerHeight * .62 };
    pointerDestination = null; pointerGesture = gestureId;
    pointer.classList.remove('is-clicking');
  }
  if (target && (!pointerDestination || t < gesture.click)) {
    const rect = target.getBoundingClientRect();
    pointerDestination = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
  }
  const show = gesture && pointerDestination && (!touch || t >= gesture.click - 200);
  if (show) {
    const surface = target?.closest('dialog[open]') || document.querySelector('dialog[open]') || document.body;
    if (pointer.parentElement !== surface) surface.appendChild(pointer);
    const progress = touch ? 1 : ease((t - gesture.start) / Math.max(1, gesture.click - gesture.start - 220));
    const x = pointerOrigin.x + (pointerDestination.x - pointerOrigin.x) * progress;
    const y = pointerOrigin.y + (pointerDestination.y - pointerOrigin.y) * progress;
    pointerPosition = { x, y };
    pointer.style.transform = `translate(${x}px, ${y}px)`;
    pointer.classList.toggle('is-clicking', t >= gesture.click);
    if (progress >= 1 && target !== hoveredControl) {
      hoveredControl?.removeAttribute('data-preview-hover');
      hoveredControl?.removeAttribute('data-preview-pressed');
      hoveredControl = target; hoveredControl?.setAttribute('data-preview-hover', '');
    }
    hoveredControl?.toggleAttribute('data-preview-pressed', t >= gesture.click);
  } else {
    hoveredControl?.removeAttribute('data-preview-hover');
    hoveredControl?.removeAttribute('data-preview-pressed'); hoveredControl = null;
  }
  pointer.classList.toggle('visible', !!show);
}

async function mount() {
  await router.replace('/home');
  root = app.mount('#app');
  pointer = document.createElement('div');
  pointer.className = `preview-pointer ${innerWidth <= 760 ? 'is-touch' : ''}`;
  document.body.appendChild(pointer);
  // Keep the phone's physical corners inside its own document. Embedded
  // browser surfaces can composite fixed content above an outer iframe clip.
  bezel = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  bezel.classList.add('preview-bezel');
  bezel.setAttribute('aria-hidden', 'true');
  const edge = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  bezel.appendChild(edge);
  document.body.appendChild(bezel);
  // Warm the saved illustration before playback reaches the real View.
  const illustration = new Image();
  illustration.src = snapshot.view.illustration.src;
  await Promise.race([
    Promise.allSettled([document.fonts.ready, illustration.decode()]),
    new Promise(resolve => setTimeout(resolve, 3000)),
  ]);
  prepared = true;
  if (window.parent === window) {
    // A standalone document can show a specific frame for visual review.
    document.body.classList.add('preview-still');
    const params = new URLSearchParams(location.search);
    await renderFrame({ scene: ['palette', 'gallery', 'exhibition', 'access-home', 'access-header', 'access-sidebar', 'access-gallery', 'access-exhibition'].includes(params.get('scene')) ? params.get('scene') : 'home', elapsed: Math.max(0, Number(params.get('at')) || 0), playing: false, touch: innerWidth <= 1180 && innerHeight <= 600 || innerWidth <= 760, exhibition: innerWidth > 600 || ['exhibition', 'access-exhibition'].includes(params.get('scene')), dark: params.get('theme') === 'dark', cornerRadius: Number(params.get('radius')) || 0 });
  }
  window.parent.postMessage({ type: 'archive-preview-ready' }, location.origin);
}

window.addEventListener('message', event => {
  if (event.source !== window.parent || event.origin !== location.origin || event.data?.type !== 'archive-preview-frame') return;
  renderFrame(event.data);
});
mount();
